    String phase="",first,second,third;Fixture backend;TenNotaPanel fixture;
    static final String A="A".repeat(14999)+"a",B="B".repeat(14999)+"b";
    @Override public void onCreate(Bundle args){phase=args==null?"":args.getString("phase","");super.onCreate(args);}
    @Override public void onStart(){Bundle out=new Bundle();try{
        store=new DesktopStore(getTargetContext());
        if(!phase.equals("cold"))store.prefs.edit().remove(TenNotaDrafts.KEY).remove(TenDesktops.KEY).remove(TenDesktopItems.KEY).remove("ten_nota_history").putString("ten_nota_draft","open Audible").remove("ten_nota_imported").remove("ten_nota_task").remove("ten_nota_reply").commit();
        store.prefs.edit().putInt("startup_mode",2).putBoolean("welcome_on_start",false).putBoolean("reduce_motion",true).putBoolean("taskbar_apps",false).commit();
        getTargetContext().getSharedPreferences(StorageAccess.PREFS,0).edit().putBoolean("seen",true).commit();
        getTargetContext().getSharedPreferences(StartupExperience.SESSION,0).edit().putBoolean("seen",true).putBoolean("welcome_seen",true).putBoolean(StartupExperience.HOME_OFFERED,true).commit();
        ShellTestSetup.complete(getTargetContext());
        getTargetContext().getSharedPreferences("ten-nota-ai-privacy",0).edit().putBoolean("cloud-allowed",false).putInt("consent-version",1).commit();
        home=(MainActivity)startActivitySync(new Intent(Intent.ACTION_MAIN).setComponent(new ComponentName(getTargetContext(),MainActivity.class)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));root=home.getWindow().getDecorView();await(()->TenSmoke.description(root,"Start menu")!=null,"Shell ready");
        if(phase.equals("cold")){cold();out.putString("stream","PASS: two full ordinary Nota drafts, replies, tasks and origins restored independently after a stopped process, with no private passage in preferences or backup\n");}
        else{migration();guides();assistantFixture();boundaries();desktops();privateState();recreation();layouts();windowTouches();prepareCold();out.putString("stream","PASS: six guides/hints, reply-only Copy/Save, real controlled assistant reply and stop/late result, writing/history/private/legacy boundaries, independent 15000-character desktop drafts/replies/tasks/origins, move ownership, safe session recreation and backup validation, both landscape rotations and light/dark accents, compact/keyboard layout and window touch ownership\n");}
        finish(Activity.RESULT_OK,out);
    }catch(Throwable e){try{shot("ten20-nota-failure");}catch(Exception ignored){}out.putString("stream","FAIL: "+android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,out);}}
    TenDesktops desks(){try{Field f=MainActivity.class.getDeclaredField("tenDesktops");f.setAccessible(true);return(TenDesktops)f.get(home);}catch(Exception e){throw new RuntimeException(e);}}
    TenNotaPanel panel(){return(TenNotaPanel)windows().get("@nota").body;}
    void fresh(){TenSmoke.description(panel(),"New command").performClick();}
    void migration()throws Exception{
        ui(()->{first=desks().current();home.open("@nota");TenNotaPanel p=panel();check(p.importedDraft&&p.input.getText().toString().equals("open Audible"),"Legacy draft defaults to writing");p.task.setSelection(5);p.send.performClick();check(p.pending.isEmpty()&&p.actionChoices.getChildCount()==0,"Legacy draft cannot execute");second=desks().create();desks().select(second);home.open("@nota");check(panel().input.length()==0&&panel().lastReply.isEmpty(),"Migration does not clone the global draft");desks().select(first);fresh();});
    }
    void guides()throws Exception{
        String[] summaries={"Ask questions, write new content, or give a simple app command.","Explore ideas, suggestions and new directions for a topic.","Correct spelling, grammar and punctuation while keeping your wording.","Improve clarity, tone and flow while keeping your meaning.","Condense a passage into its key points and important details.","Open apps and settings, switch apps, or search the web and linked files."};
        String[] hints={"Ask a question or describe what to write","Enter a topic or goal for ideas","Paste or type text to proofread","Paste or type text to polish","Paste or type text to summarize","Try open ChatGPT or open Calculator"};
        String note=store.prefs.getString("note","");
        for(int i=0;i<6;i++){final int n=i;ui(()->panel().task.setSelection(n));waitForIdleSync();ui(()->{TenNotaPanel p=panel();check(p.taskSummary.getText().toString().equals(summaries[n])&&p.input.getHint().toString().equals(hints[n]),"Category summary and hint "+n);check(p.guidance.getText().toString().contains("then press Send")&&p.guidance.isShown(),"Visible category instructions "+n);check(p.answer.getVisibility()==View.GONE&&!p.copyReply.isEnabled()&&!p.saveReply.isEnabled(),"Guidance has no reply actions");p.copyReply.performClick();p.saveReply.performClick();check(store.prefs.getString("note","").equals(note)&&p.lastReply.isEmpty(),"Guidance cannot be saved");});shot("ten20-nota-mode-"+i);}
    }
    static final class Fixture implements LocalAI.Backend {
        final AtomicInteger calls=new AtomicInteger();volatile CompletableFuture<String> next=new CompletableFuture<>();volatile String prompt="";
        public CompletableFuture<Integer> status(){return CompletableFuture.completedFuture(FeatureStatus.AVAILABLE);}
        public CompletableFuture<Void> download(DownloadCallback cb){throw new AssertionError("No model download");}
        public CompletableFuture<Integer> tokens(String p,String t){return CompletableFuture.completedFuture(10);}
        public CompletableFuture<String> generate(String p,String t){prompt=p;calls.incrementAndGet();return next;}
        public void close(){}
    }
    void assistantFixture()throws Exception{
        ui(()->{windows().get("@nota").closeWindow();backend=new Fixture();fixture=new TenNotaPanel(home,store,first,backend);try{Method m=MainActivity.class.getDeclaredMethod("window",String.class,String.class,View.class);m.setAccessible(true);m.invoke(home,"@nota","Nth Nota",fixture);}catch(Exception e){throw new RuntimeException(e);}fixture.context(new TenNotaContext("Reviewed selection","open Audible",false));fixture.send.performClick();});
        await(()->backend.calls.get()==1,"Controlled local backend receives Send");check(backend.prompt.contains("open Audible")&&backend.prompt.contains("Summarize"),"Only reviewed composer and task sent");backend.next.complete("open Audible");await(()->panel().lastReply.equals("open Audible")&&panel().pending.isEmpty(),"Real assistant result reaches panel");
        for(int i=0;i<6;i++){final int n=i;ui(()->panel().task.setSelection(n));waitForIdleSync();ui(()->{TenNotaPanel p=panel();check(p.guidance.isShown()&&p.answer.isShown()&&p.lastReply.equals("open Audible")&&p.copyReply.isEnabled()&&p.saveReply.isEnabled(),"Reply remains beneath selected guide");check(TenNotaDrafts.read(store,first).optString("reply").equals("open Audible"),"Guide does not replace reply cache");});}
        ui(()->{TenNotaPanel p=panel();p.copyReply.performClick();check(home.getSystemService(android.content.ClipboardManager.class).getPrimaryClip().getItemAt(0).getText().toString().equals("open Audible"),"Copy uses real reply");String note=store.prefs.getString("note","");p.saveReply.performClick();check(store.prefs.getString("note","").equals(note+(note.isEmpty()?"":"\n\n")+"open Audible"),"Save uses real reply only");fresh();p.task.setSelection(1);p.input.setText("Ideas for a journal");backend.next=new CompletableFuture<>();p.send.performClick();});
        await(()->backend.calls.get()==2,"Second fixture request begins");CompletableFuture<String> late=backend.next;
        ui(()->{TenSmoke.description(panel(),"Stop").performClick();fresh();});late.complete("Late reply must be ignored");await(()->!fixture.assistant.local.isBusy(),"Cancelled SDK future settles");ui(()->check(panel().lastReply.isEmpty()&&panel().pending.isEmpty(),"Stop and New command reject late replies"));
    }
    void boundaries()throws Exception{
        AtomicInteger launches=new AtomicInteger();ActivityMonitor monitor=new ActivityMonitor(){@Override public ActivityResult onStartActivity(Intent intent){if(intent.getComponent()!=null&&intent.getComponent().getPackageName().equals("com.nthexperience.desktop.fixture")){launches.incrementAndGet();return new ActivityResult(Activity.RESULT_CANCELED,null);}return null;}};addMonitor(monitor);
        try{
            await(()->home.notaAppTargets().stream().anyMatch(a->a.title.equals("Audible")),"Fixture catalog loaded");
            ui(()->{TenNotaPanel p=panel();fresh();p.input.setText("open Audible");p.send.performClick();check(launches.get()==1&&p.pending.isEmpty(),"Fresh exact app opens once without AI");p.input.setText("open Nota duplicate");p.send.performClick();check(p.actionChoices.getChildCount()==2&&launches.get()==1,"Ambiguous apps wait for selection");check(!p.actionChoices.getChildAt(0).getContentDescription().equals(p.actionChoices.getChildAt(1).getContentDescription()),"Same package/activity choices are distinguishable");p.input.setText("edited");check(p.actionChoices.getChildCount()==0,"Edit clears stale choices");p.context(new TenNotaContext("Source","open Audible",false));p.contextLabel.performClick();});systemClick("Clear context");
            ui(()->{TenNotaPanel p=panel();p.task.setSelection(5);p.send.performClick();check(p.importedDraft&&p.context==null&&p.pending.isEmpty()&&launches.get()==1,"Cleared source remains writing");p.restoreState(TenNotaState.redacted());p.input.setText("open Audible");p.task.setSelection(5);p.send.performClick();check(launches.get()==1&&p.pending.isEmpty(),"Private composer stays writing");fresh();TenSmoke.description(p,"History").performClick();});awaitSystem("Recent chats");systemClick("open Audible");await(()->panel().importedDraft,"History request restored as writing");
            ui(()->{TenNotaPanel p=panel();p.task.setSelection(5);p.send.performClick();check(p.importedDraft&&launches.get()==1&&p.pending.isEmpty(),"History cannot execute: origin="+p.importedDraft+", launches="+launches.get()+", pending="+p.pending+", composer="+p.input.getText());fresh();p.input.setText("nonsense writing command");p.send.performClick();check(p.pending.isEmpty()&&p.assistant.active.isEmpty(),"Apps mode unknown command stays local");});
        }finally{removeMonitor(monitor);}
    }
    void seed(TenNotaPanel p,String text,int task,String reply,boolean imported){try{p.restoreState(TenNotaState.ordinary(text,task,imported,reply,imported?"Reviewed writing":"",true,false));p.input.setText(text);}catch(Exception e){throw new RuntimeException(e);}}
    void desktops()throws Exception{
        ui(()->{seed(panel(),A,2,"reply A",true);desks().select(second);home.open("@nota");seed(panel(),B,5,"reply B",false);check(panel().context==null&&panel().pending.isEmpty()&&panel().actionChoices.getChildCount()==0,"Restore has no executable authority");desks().select(first);check(panel().input.getText().toString().equals(A)&&panel().lastReply.equals("reply A")&&panel().task.getSelectedItemPosition()==2&&panel().importedDraft,"Desktop A is independent");check(captured().length()<30000,"Session references avoid duplicating full drafts in Android saved state");DesktopWindow moving=windows().get("@nota");third=desks().create();check(desks().move(moving,third),"Move Nota to unused desktop");desks().select(third);check(panel().input.getText().toString().equals(A)&&panel().desktopId.equals(third),"Moved window retains full state and changes owner");check(!TenNotaDrafts.banks(store).has(first)&&TenNotaDrafts.read(store,third).optString("draft").equals(A),"Scoped cache moves with the window");check(desks().move(moving,first),"Move Nota back");desks().select(first);});
    }
    String captured(){try{Method m=MainActivity.class.getDeclaredMethod("captureSession");m.setAccessible(true);return((JSONObject)m.invoke(home)).toString();}catch(Exception e){throw new RuntimeException(e);}}
    void privateState()throws Exception{
        ui(()->{desks().select(third);home.open("@nota");panel().context(new TenNotaContext("Private source","PRIVATE_PASSAGE_20",true));panel().pending="private_fixture";try{panel().result(new JSONObject().put("id","private_fixture").put("text","PRIVATE_REPLY_20").put("local",true));JSONObject snapshot=ToolViewState.capture(panel());check(!snapshot.toString().contains("PRIVATE_")&&snapshot.toString().contains("private"),"Private session contains only redaction marker");ToolViewState.restore(panel(),new JSONObject().put("/6",new JSONObject().put("text","stale snapshot")));check(panel().input.getText().toString().equals("PRIVATE_PASSAGE_20"),"Legacy generic snapshot ignored");String all=store.prefs.getAll().toString()+captured()+DesktopBackup.snapshot(store);check(!all.contains("PRIVATE_PASSAGE_20")&&!all.contains("PRIVATE_REPLY_20"),"Private passage/reply absent from preferences history backup and every desktop session");JSONObject backup=DesktopBackup.snapshot(store);DesktopBackup.Plan parsed=DesktopBackup.parse(backup.toString());check(parsed.values.containsKey(TenNotaDrafts.KEY),"Backup retains scoped drafts");JSONObject banks=new JSONObject((String)parsed.values.get(TenNotaDrafts.KEY));check(banks.getJSONObject(first).getString("draft").equals(A)&&banks.getJSONObject(second).getString("draft").equals(B),"Full independent drafts in backup");banks.getJSONObject(second).put("task",6);backup.getJSONObject("settings").getJSONObject(TenNotaDrafts.KEY).put("value",banks.toString());boolean rejected=false;try{DesktopBackup.parse(backup.toString());}catch(JSONException expected){rejected=true;}check(rejected,"Invalid scoped task rejected before mutation");check(!parsed.values.containsKey("cloud-allowed"),"Backup does not grant cloud consent");}catch(Exception e){throw new RuntimeException(e);}});
    }
    void recreation()throws Exception{
        BlockingQueue<MainActivity> resumed=new LinkedBlockingQueue<>();Application app=(Application)getTargetContext().getApplicationContext();Application.ActivityLifecycleCallbacks cb=new Application.ActivityLifecycleCallbacks(){public void onActivityResumed(Activity a){if(a instanceof MainActivity)resumed.offer((MainActivity)a);}public void onActivityCreated(Activity a,Bundle b){}public void onActivityStarted(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};
        app.registerActivityLifecycleCallbacks(cb);ui(()->home.recreate());MainActivity next=resumed.poll(20,TimeUnit.SECONDS);app.unregisterActivityLifecycleCallbacks(cb);check(next!=null,"Activity recreates");home=next;root=home.getWindow().getDecorView();await(()->windows().containsKey("@nota"),"Nota window restored");
        ui(()->{check(desks().current().equals(third)&&panel().privateDraft&&panel().input.length()==0&&panel().lastReply.isEmpty(),"Private window restores empty on its own desktop");desks().select(first);check(panel().input.getText().toString().equals(A)&&panel().lastReply.equals("reply A")&&panel().importedDraft&&panel().task.getSelectedItemPosition()==2,"A survives real activity recreation");desks().select(second);check(panel().input.getText().toString().equals(B)&&panel().lastReply.equals("reply B")&&!panel().importedDraft&&panel().task.getSelectedItemPosition()==5,"B survives recreation without inheriting A or private cache");check(panel().pending.isEmpty()&&panel().actionChoices.getChildCount()==0,"No action/request replay on recreation");desks().select(first);fresh();});
    }
    void layouts()throws Exception{
        for(int orientation:new int[]{ActivityInfo.SCREEN_ORIENTATION_PORTRAIT,ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE,ActivityInfo.SCREEN_ORIENTATION_REVERSE_LANDSCAPE}){
            ui(()->home.setRequestedOrientation(orientation));await(()->(root.getWidth()>root.getHeight())==(orientation!=ActivityInfo.SCREEN_ORIENTATION_PORTRAIT),"Nota orientation settles");
            for(boolean dark:new boolean[]{false,true}){ui(()->{store.prefs.edit().putBoolean("ten_apps_dark",dark).putInt("ten_accent",dark?0xff00cc66:0xff000000).apply();home.applyTenAppearance();windows().get("@nota").maximize();panel().task.setSelection(4);});waitForIdleSync();ui(()->{TenNotaPanel p=panel();Rect r=new Rect();check(TenSmoke.description(p,"New command").getGlobalVisibleRect(r)&&r.height()>0,"New command visible in compact layout");check(p.send.getGlobalVisibleRect(new Rect()),"Send remains visible");check(p.taskSummary.getAccessibilityLiveRegion()==View.ACCESSIBILITY_LIVE_REGION_POLITE,"Category accessible updates");check(TenAppearance.contrast(p.guidance.getCurrentTextColor(),TenAppearance.background(home))>=4.5,"Guide contrast follows app theme");});shot("ten20-nota-"+orientation+(dark?"-dark":"-light"));}
        }
        try(android.os.ParcelFileDescriptor fd=getUiAutomation().executeShellCommand("settings put secure show_ime_with_hard_keyboard 1");java.io.InputStream in=new android.os.ParcelFileDescriptor.AutoCloseInputStream(fd)){while(in.read()!=-1){}}
        ui(()->{panel().input.requestFocus();home.getSystemService(android.view.inputmethod.InputMethodManager.class).showSoftInput(panel().input,android.view.inputmethod.InputMethodManager.SHOW_IMPLICIT);});
        await(()->root.getRootWindowInsets()!=null&&root.getRootWindowInsets().isVisible(WindowInsets.Type.ime()),"Real keyboard visible");
        await(()->{Rect command=new Rect(),send=new Rect();View button=TenSmoke.description(panel(),"New command");return button.getGlobalVisibleRect(command)&&command.height()>=button.getHeight()*.9f&&panel().visibleSend().getGlobalVisibleRect(send)&&send.height()>=panel().visibleSend().getHeight()*.9f;},"New command and Send accessible above keyboard");shot("ten20-nota-keyboard");ui(()->{fresh();panel().input.setText("What can you do?");panel().visibleSend().performClick();check(panel().pending.isEmpty()&&!panel().lastReply.isEmpty()&&panel().actionChoices.getChildCount()>0,"Compact Send dispatches a local request");home.getSystemService(android.view.inputmethod.InputMethodManager.class).hideSoftInputFromWindow(root.getWindowToken(),0);});await(()->!root.getRootWindowInsets().isVisible(WindowInsets.Type.ime()),"Keyboard dismissed");
        try(android.os.ParcelFileDescriptor fd=getUiAutomation().executeShellCommand("settings put secure show_ime_with_hard_keyboard 0");java.io.InputStream in=new android.os.ParcelFileDescriptor.AutoCloseInputStream(fd)){while(in.read()!=-1){}}
    }
    ViewGroup touchHost(){try{Field f=MainActivity.class.getDeclaredField("workspace");f.setAccessible(true);return(ViewGroup)f.get(home);}catch(Exception e){throw new RuntimeException(e);}}
    void windowTouches()throws Exception{
        final AtomicInteger behind=new AtomicInteger(),child=new AtomicInteger();final FrameLayout[] stage={null},body={null};final DesktopWindow[] win={null};final Button[] button={null};
        ui(()->{stage[0]=new FrameLayout(home);stage[0].setElevation(Aero.dp(home,100));touchHost().addView(stage[0],new ViewGroup.LayoutParams(-1,-1));View desktop=new View(home);desktop.setOnClickListener(v->behind.incrementAndGet());stage[0].addView(desktop,new FrameLayout.LayoutParams(-1,-1));body[0]=new FrameLayout(home);button[0]=new Button(home);button[0].setOnClickListener(v->child.incrementAndGet());body[0].addView(button[0],new FrameLayout.LayoutParams(Aero.dp(home,100),Aero.dp(home,50)));win[0]=new DesktopWindow(home,stage[0],"Touch fixture",body[0],new AeroWallpaper(home,AeroWallpaper.SEVEN),()->{},store,"@touch-fixture","portrait");stage[0].addView(win[0]);});
        ui(()->win[0].arrange(Aero.dp(home,25),Aero.dp(home,30),stage[0].getWidth()-Aero.dp(home,50),stage[0].getHeight()-Aero.dp(home,70)));waitForIdleSync();tap(body[0],body[0].getWidth()/2f,body[0].getHeight()-Aero.dp(home,30));check(behind.get()==0,"Blank window owns gesture");tap(button[0],button[0].getWidth()/2f,button[0].getHeight()/2f);check(child.get()==1,"Child still receives gesture");tap(stage[0],5,stage[0].getHeight()/2f);check(behind.get()==1,"Uncovered desktop usable");ui(()->((ViewGroup)stage[0].getParent()).removeView(stage[0]));
    }
    void tap(View v,float x,float y)throws Exception{int[] p=new int[2];ui(()->v.getLocationOnScreen(p));long t=SystemClock.uptimeMillis();MotionEvent down=MotionEvent.obtain(t,t,0,p[0]+x,p[1]+y,0),up=MotionEvent.obtain(t,t+60,1,p[0]+x,p[1]+y,0);sendPointerSync(down);sendPointerSync(up);down.recycle();up.recycle();waitForIdleSync();}
    void prepareCold()throws Exception{ui(()->{seed(panel(),A,2,"reply A",true);desks().select(second);seed(panel(),B,5,"reply B",false);desks().select(first);check(TenNotaDrafts.read(store,first).optString("draft").equals(A)&&TenNotaDrafts.read(store,second).optString("draft").equals(B),"Cold fixtures reach scoped store: closed="+panel().closed+", A="+TenNotaDrafts.read(store,first).optString("draft").length()+", B="+TenNotaDrafts.read(store,second).optString("draft").length());check(store.prefs.edit().putBoolean("nota_cold_ready",true).commit(),"Cold process fixture flushed to disk");});}
